_PKG = __package__.rpartition('.')[0]

def _url(url):
    return ('wm.url_open', {'url': url})

def _prop(path, value=None):
    return ('prop', path, {} if value is None else {'value': value})

def _tangent(kind, side='BOTH'):
    return ('allset.set_tangent', {'kind': kind, _dcc_source('side'): side})

def _infinity(side, mode):
    return ('allset.curve_infinity', {_dcc_source('side'): side, 'mode': mode})

def _key(action):
    return ('allset.key_edit', {'action': action})

def _uv_tool(idname):
    return ('wm.tool_set_by_id', {'name': idname, 'space_type': 'IMAGE_EDITOR'})
TANGENT_KINDS = {_dcc_source('Spline'): 'SPLINE', _dcc_source('Linear'): 'LINEAR', _dcc_source('Clamped'): 'CLAMPED', _dcc_source('Stepped'): 'STEPPED', _dcc_source('Stepped Next'): 'STEPPED_NEXT', _dcc_source('Flat'): 'FLAT', _dcc_source('Fixed'): 'FIXED', _dcc_source('Plateau'): 'PLATEAU'}
AUTO_KINDS = (_dcc_source('Auto Span'), _dcc_source('Auto Ease'), _dcc_source('Auto Mix'), _dcc_source('Auto Custom'))
_PREFS_ANIMATION = ('screen.userpref_show', {'section': 'ANIMATION'})
DEFAULT_TANGENT_LABELS = {**{label: 'AUTO' for label in AUTO_KINDS}, _dcc_source('Spline'): 'SPLINE', _dcc_source('Clamped'): 'CLAMPED', _dcc_source('Plateau'): 'PLATEAU', _dcc_source('Linear'): 'LINEAR', _dcc_source('Flat'): 'FLAT', _dcc_source('Stepped'): 'STEPPED'}

def _tangents_menu(ed):
    m = {f'{ed}/Tangents/Auto/{label}': _tangent('AUTO') for label in AUTO_KINDS}
    m.update({f'{ed}/Tangents/{label}': _tangent(kind) for (label, kind) in TANGENT_KINDS.items()})
    for (side, sub) in (('IN', _dcc_source('In Tangent')), ('OUT', _dcc_source('Out Tangent'))):
        m.update({f'{ed}/Tangents/{sub}/Auto/{label}': _tangent('AUTO', side) for label in AUTO_KINDS})
        m.update({f'{ed}/Tangents/{sub}/{label}': _tangent(kind, side) for (label, kind) in TANGENT_KINDS.items()})
    for (sub, pref) in ((_dcc_source('Default In Tangent'), 'default_in_tangent'), (_dcc_source('Default Out Tangent'), 'default_out_tangent')):
        m.update({f'{ed}/Tangents/{sub}/{label}': _prop(f'addon_prefs.{pref}', kind) for (label, kind) in DEFAULT_TANGENT_LABELS.items() if not (label == _dcc_source('Stepped') and sub == _dcc_source('Default In Tangent'))})
    m[f'{ed}/Tangents/Break Tangents'] = _tangent('BREAK')
    m[f'{ed}/Tangents/Unify Tangents'] = _tangent('UNIFY')
    return m

def _channel_commands(ed, menu, graph):
    """Bake / Mute / Lock: the Graph Editor's Curves menu, the Dope Sheet's Channels menu (Maya 2026)."""
    return {f'{ed}/{menu}/Bake Channel': 'graph.bake_keys' if graph else 'action.bake_keys', f'{ed}/{menu}/Mute Channel': ('anim.channels_setting_enable', {'type': 'MUTE'}), f'{ed}/{menu}/Unmute Channel': ('anim.channels_setting_disable', {'type': 'MUTE'}), f'{ed}/{menu}/Lock Channel': ('anim.channels_setting_enable', {'type': 'PROTECT'}), f'{ed}/{menu}/Unlock Channel': ('anim.channels_setting_disable', {'type': 'PROTECT'})}

def _curves_menu(ed, graph):
    m = _channel_commands(ed, _dcc_source('Curves'), graph)
    for (side, sub) in (('PRE', _dcc_source('Pre Infinity')), ('POST', _dcc_source('Post Infinity'))):
        for (label, mode) in ((_dcc_source('Cycle'), 'CYCLE'), (_dcc_source('Cycle with Offset'), 'CYCLE_OFFSET'), (_dcc_source('Oscillate'), 'OSCILLATE'), (_dcc_source('Linear'), 'LINEAR'), (_dcc_source('Constant'), 'CONSTANT')):
            m[f'{ed}/Curves/{sub}/{label}'] = _infinity(side, mode)
    m.update({f'{ed}/Curves/Simplify Curve': 'graph.clean' if graph else 'action.clean', f'{ed}/Curves/Key Reducer Filter': 'graph.decimate' if graph else 'action.clean'})
    if graph:
        m.update({f'{ed}/Curves/Isolate Curve': ('graph.hide', {'unselected': True}), f'{ed}/Curves/Smooth Filter (Butterworth)': 'graph.butterworth_smooth', f'{ed}/Curves/Smooth Filter (Gaussian)': 'graph.gaussian_smooth', f'{ed}/Curves/Euler Filter': 'graph.euler_filter', f'{ed}/Curves/Resample Curve': 'graph.bake_keys'})
    else:
        m.update({f'{ed}/Curves/{label}': ('allset.dope_graph_op', {'command': cmd}) for (label, cmd) in ((_dcc_source('Isolate Curve'), 'ISOLATE'), (_dcc_source('Smooth Filter (Butterworth)'), 'BUTTERWORTH'), (_dcc_source('Smooth Filter (Gaussian)'), 'GAUSSIAN'), (_dcc_source('Euler Filter'), 'EULER'), (_dcc_source('Resample Curve'), 'RESAMPLE'))})
    return m

